-- ShelfVision AI - Walmart Chile: estructura y datos de prueba de la base (ítem #62).
--
-- Motor: SQLite 3 (el que usa la app web Django, ver web/settings.py).
-- Uso:   sqlite3 shelfvision.db < shelfvision.sql
-- La estructura es la que crea `python manage.py migrate` (web/models.py y las
-- migraciones web 0001-0006, más las tablas de auth, contenttypes y sessions de
-- Django); tests/test_sql_script.py comprueba que ambas coincidan. Como el script
-- registra las migraciones como aplicadas, una base creada con él también
-- funciona con la app (`migrate` no tiene nada que hacer).
--
-- Los datos son ficticios (personas, RUT, correos, cámaras y resultados de una
-- góndola sintética; no hay fotos de SKU-110K ni de Walmart). Las fotos anotadas
-- que cita `web_analysis.annotated` no se incluyen: la vista de un análisis de
-- prueba no mostrará la imagen. Clave de los cuatro usuarios: prueba-1234
-- (el RUT es el nombre de usuario; el último está bloqueado por intentos fallidos).
--
-- Las columnas `result` y `calibracion` son JSON (PipelineResult.to_dict() y
-- el formato de OpenCV de LensCalibration). No hay tabla de productos ni de
-- góndolas: la ubicación es el par pasillo/góndola de cada cámara y análisis.
-- `web_analysis.estado` vacío = análisis sin quiebre; solo hay una alerta abierta
-- (activa o en_proceso) por góndola.

PRAGMA foreign_keys = ON;

BEGIN;

CREATE TABLE "django_migrations" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "app" varchar(255) NOT NULL,
    "name" varchar(255) NOT NULL,
    "applied" datetime NOT NULL
);

CREATE TABLE "django_content_type" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "app_label" varchar(100) NOT NULL,
    "model" varchar(100) NOT NULL
);
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");

CREATE TABLE "auth_permission" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED,
    "codename" varchar(100) NOT NULL,
    "name" varchar(255) NOT NULL
);
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");

CREATE TABLE "auth_group" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "name" varchar(150) NOT NULL UNIQUE
);

CREATE TABLE "auth_group_permissions" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED,
    "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");

CREATE TABLE "django_session" (
    "session_key" varchar(40) NOT NULL PRIMARY KEY,
    "session_data" text NOT NULL,
    "expire_date" datetime NOT NULL
);
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");

CREATE TABLE "web_user" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "password" varchar(128) NOT NULL,
    "last_login" datetime NULL,
    "is_superuser" bool NOT NULL,
    "username" varchar(150) NOT NULL UNIQUE,
    "first_name" varchar(150) NOT NULL,
    "last_name" varchar(150) NOT NULL,
    "is_staff" bool NOT NULL,
    "is_active" bool NOT NULL,
    "date_joined" datetime NOT NULL,
    "email" varchar(254) NOT NULL UNIQUE,
    "failed_logins" smallint unsigned NOT NULL CHECK ("failed_logins" >= 0),
    "locked_until" datetime NULL
);

CREATE TABLE "web_user_groups" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "user_id" bigint NOT NULL REFERENCES "web_user" ("id") DEFERRABLE INITIALLY DEFERRED,
    "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE UNIQUE INDEX "web_user_groups_user_id_group_id_ad6e87b6_uniq" ON "web_user_groups" ("user_id", "group_id");
CREATE INDEX "web_user_groups_user_id_ddeacfa4" ON "web_user_groups" ("user_id");
CREATE INDEX "web_user_groups_group_id_b03a95c5" ON "web_user_groups" ("group_id");

CREATE TABLE "web_user_user_permissions" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "user_id" bigint NOT NULL REFERENCES "web_user" ("id") DEFERRABLE INITIALLY DEFERRED,
    "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED
);
CREATE UNIQUE INDEX "web_user_user_permissions_user_id_permission_id_b62696d3_uniq" ON "web_user_user_permissions" ("user_id", "permission_id");
CREATE INDEX "web_user_user_permissions_user_id_19dddb18" ON "web_user_user_permissions" ("user_id");
CREATE INDEX "web_user_user_permissions_permission_id_360139a1" ON "web_user_user_permissions" ("permission_id");

CREATE TABLE "web_analysis" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "created_at" datetime NOT NULL,
    "photo_name" varchar(255) NOT NULL,
    "free_fraction" real NOT NULL,
    "critical" bool NOT NULL,
    "result" text NOT NULL CHECK ((JSON_VALID("result") OR "result" IS NULL)),
    "annotated" varchar(100) NOT NULL,
    "created_by_id" bigint NULL REFERENCES "web_user" ("id") DEFERRABLE INITIALLY DEFERRED,
    "pasillo" varchar(20) NOT NULL,
    "gondola" varchar(20) NOT NULL,
    "estado" varchar(12) NOT NULL,
    "taken_by_id" bigint NULL REFERENCES "web_user" ("id") DEFERRABLE INITIALLY DEFERRED,
    "estado_at" datetime NULL
);
CREATE INDEX "web_analysis_created_by_id_9f0a4d4e" ON "web_analysis" ("created_by_id");
CREATE INDEX "web_analysis_taken_by_id_f078d3b4" ON "web_analysis" ("taken_by_id");

CREATE TABLE "web_config" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "umbral" smallint unsigned NOT NULL CHECK ("umbral" >= 0)
);

CREATE TABLE "web_camera" (
    "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT,
    "nombre" varchar(60) NOT NULL UNIQUE,
    "pasillo" varchar(20) NOT NULL,
    "gondola" varchar(20) NOT NULL,
    "calibracion" text NULL CHECK ((JSON_VALID("calibracion") OR "calibracion" IS NULL)),
    CONSTRAINT "una_camara_por_gondola" UNIQUE ("pasillo", "gondola")
);

